local d = {}
for a = 1, #c, 5 do
  local e = 0
  for h = a, a + 4 do e = e * 85 + c:byte(h) - 33 end
  d[#d + 1] = string.pack(">I4", e)
end
local f, b = table.concat(d), {}
for a = 1, #f, 16 do
  local x, y = string.unpack("<dd", f, a)
  b[#b + 1] = {x, y}
end
return {
  at = function(g) return b[math.floor(g / 10) - 99] end
}
